<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';require_once __DIR__.'/feature_helpers.php';
$db=saas_db();$slug=trim((string)($_GET['slug']??''));if($slug===''){http_response_code(404);exit('Tour not found.');}
$q=$db->prepare("SELECT t.*,o.name organization_name,o.currency organization_currency,pp.status page_status,pp.theme_key,pp.title page_title,pp.subtitle,pp.cover_image,pp.logo_image,pp.primary_color,pp.secondary_color,pp.seo_title,pp.seo_description FROM tours t JOIN organizations o ON o.id=t.organization_id JOIN tour_public_pages pp ON pp.tour_id=t.id WHERE t.slug=? AND t.status IN ('DRAFT','ACTIVE','CLOSED') AND pp.status IN ('PUBLISHED','CLOSED') AND o.status='ACTIVE' LIMIT 1");$q->execute([$slug]);$tour=$q->fetch();if(!$tour){http_response_code(404);exit('Tour not found or registration is not public.');}
$pageTitle=trim((string)($tour['page_title']??''));if($pageTitle==='')$pageTitle=trim((string)($tour['name']??'Tour'));$subtitle=trim((string)($tour['subtitle']??''));$fee=(float)($tour['default_fee']??0);$currency=trim((string)($tour['organization_currency']??'BDT'))?:'BDT';$description=trim((string)($tour['description']??''));$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=trim((string)($_SERVER['HTTP_X_FORWARDED_HOST']??$_SERVER['HTTP_HOST']??''));$publicUrl=$host!==''?$scheme.'://'.$host.'/tour/'.rawurlencode((string)$tour['slug']):'/tour/'.rawurlencode((string)$tour['slug']);$appBase=rtrim(dirname((string)($_SERVER['SCRIPT_NAME']??'/')),'/');$passengerAuthPath=($appBase?:'').'/passenger_auth.php';$publicBookingPath=($appBase?:'').'/public_booking.php';$features=saas_enabled_features((int)$tour['id']);
function public_tour_setting(PDO $db,int $tourId,string $key,string $default=''):string{$q=$db->prepare('SELECT setting_value FROM tour_settings WHERE tour_id=? AND setting_key=? LIMIT 1');$q->execute([$tourId,$key]);return (string)($q->fetchColumn()??$default);}
$schedule=public_tour_setting($db,(int)$tour['id'],'schedule');
$notes=public_tour_setting($db,(int)$tour['id'],'notes');
$transport=public_tour_setting($db,(int)$tour['id'],'default_transport','NONE');
$scheduleLines=array_values(array_filter(array_map('trim',preg_split('/\\r?\\n/',$schedule))));
$q=$db->prepare("SELECT name,bus_number,layout_type,total_seats,status FROM buses WHERE tour_id=? AND status='ACTIVE' ORDER BY id");$q->execute([(int)$tour['id']]);$publicBuses=$q->fetchAll();
$q=$db->prepare("SELECT room_no,room_type,capacity,status FROM rooms WHERE tour_id=? ORDER BY id");$q->execute([(int)$tour['id']]);$publicRooms=$q->fetchAll();
$closed=$tour['page_status']==='CLOSED'||$tour['status']==='CLOSED';$error='';$success='';$bookingLink='';
if($_SERVER['REQUEST_METHOD']==='POST'&&!$closed){
 try{
  saas_check_csrf();
  $name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$email=strtolower(trim((string)($_POST['email']??'')));$fee=(float)$tour['default_fee'];
  if($name===''||$phone==='')throw new RuntimeException('Name and phone number are required.');
  if(strlen($name)>180||strlen($phone)>50||strlen($email)>190)throw new RuntimeException('One or more fields are too long.');
  if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Please enter a valid email address.');
  $db->beginTransaction();
  $q=$db->prepare('SELECT id,full_name,email FROM passenger_profiles WHERE organization_id=? AND phone=? ORDER BY id LIMIT 1 FOR UPDATE');$q->execute([(int)$tour['organization_id'],$phone]);$existingProfile=$q->fetch();
  if($existingProfile){$profileId=(int)$existingProfile['id'];$storedEmail=strtolower(trim((string)($existingProfile['email']??'')));if($storedEmail===''||$email===''||!hash_equals($storedEmail,$email))throw new RuntimeException('This phone number is already associated with an existing passenger profile. Please use the registered email address or contact the organizer.');}
  else{$q=$db->prepare('INSERT INTO passenger_profiles(organization_id,full_name,phone,email) VALUES(?,?,?,?)');$q->execute([(int)$tour['organization_id'],$name,$phone,$email?:null]);$profileId=(int)$db->lastInsertId();}
  $q=$db->prepare('SELECT id,status FROM tour_passengers WHERE tour_id=? AND passenger_profile_id=? FOR UPDATE');$q->execute([(int)$tour['id'],$profileId]);$existing=$q->fetch();if($existing&&$existing['status']!=='CANCELLED')throw new RuntimeException('This passenger is already registered for this tour.');
  $token=bin2hex(random_bytes(32));$tokenHash=hash('sha256',$token);
  if($existing){$q=$db->prepare("UPDATE tour_passengers SET status='PENDING',registration_source='PUBLIC',fee=?,discount=0,booking_access_token_hash=?,booking_access_token_created_at=NOW(),booking_access_token_revoked_at=NULL WHERE id=?");$q->execute([$fee,$tokenHash,(int)$existing['id']]);}
  else{$q=$db->prepare("INSERT INTO tour_passengers(tour_id,passenger_profile_id,status,registration_source,fee,discount,booking_access_token_hash,booking_access_token_created_at) VALUES(?,?, 'PENDING','PUBLIC',?,0,?,NOW())");$q->execute([(int)$tour['id'],$profileId,$fee,$tokenHash]);}
  $db->commit();$bookingLink=$publicBookingPath.'?slug='.rawurlencode((string)$tour['slug']).'&token='.rawurlencode($token);$success='Registration submitted successfully. Your booking is pending confirmation.';
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not complete registration. Please try again.';}
}
$theme=in_array((string)$tour['theme_key'],['classic','travel','event'],true)?(string)$tour['theme_key']:'classic';$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)$tour['primary_color'])?$tour['primary_color']:'#155eef';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)$tour['secondary_color'])?$tour['secondary_color']:'#0f172a';
